fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Ensure the inputs are non‐empty and of the same length
    assert!(!a.is_empty(), "Input vectors must be non-empty");
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Consume both vectors, XOR corresponding elements, and collect into a new Vec<u8>
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x ^ y)
     .collect()
}

